CREATE TABLE public.supervisor_rosters (company_id uuid PRIMARY KEY REFERENCES public.companies(id), start_date date NOT NULL DEFAULT current_date, rotation_days int NOT NULL DEFAULT 7 CHECK(rotation_days IN (1,2,3,7,14)), per_shift int NOT NULL DEFAULT 1 CHECK(per_shift>=1), member_order uuid[] NOT NULL DEFAULT '{}', updated_by uuid, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.supervisor_rosters TO authenticated; GRANT ALL ON public.supervisor_rosters TO service_role;
ALTER TABLE public.supervisor_rosters ENABLE ROW LEVEL SECURITY;
CREATE POLICY supervisor_roster_read ON public.supervisor_rosters FOR SELECT TO authenticated USING(company_id=public.current_company_id() AND public.member_is_active(auth.uid()) AND public.company_module_access(company_id,'standby'));
CREATE TABLE public.standby_roster_audit (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), company_id uuid NOT NULL, track text NOT NULL, config jsonb NOT NULL, changed_by uuid, changed_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.standby_roster_audit TO authenticated; GRANT ALL ON public.standby_roster_audit TO service_role;
ALTER TABLE public.standby_roster_audit ENABLE ROW LEVEL SECURITY;
CREATE POLICY roster_audit_manager ON public.standby_roster_audit FOR SELECT TO authenticated USING(company_id=public.current_company_id() AND public.is_company_manager() AND public.member_is_active(auth.uid()));
ALTER TABLE public.standby_swaps ADD COLUMN track text NOT NULL DEFAULT 'technician' CHECK(track IN ('technician','supervisor'));
CREATE OR REPLACE FUNCTION public.standby_track_ids(_company uuid,_date date,_track text) RETURNS uuid[] LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE st date;rot int;per int;o uuid[];ids uuid[]='{}';n int;blk int;first int;k int;sw record; BEGIN
IF _track='technician' THEN SELECT standby_start,standby_rotation_days,standby_per_shift,standby_order INTO st,rot,per,o FROM public.company_settings WHERE company_id=_company; ELSIF _track='supervisor' THEN SELECT start_date,rotation_days,per_shift,member_order INTO st,rot,per,o FROM public.supervisor_rosters WHERE company_id=_company; ELSE RETURN ids; END IF;
n=coalesce(cardinality(o),0);IF n=0 THEN RETURN ids; END IF;per=greatest(1,least(per,n));blk=floor((_date-st)::numeric/greatest(1,rot));first=(((blk*per)%n)+n)%n;
FOR k IN 0..per-1 LOOP ids=ids||o[((first+k)%n)+1]; END LOOP;
FOR sw IN SELECT requester_id,target_id FROM public.standby_swaps WHERE company_id=_company AND track=_track AND _date BETWEEN swap_date AND coalesce(end_date,swap_date) AND status='accepted' AND manager_approved ORDER BY created_at,id LOOP IF sw.requester_id=ANY(ids) AND NOT sw.target_id=ANY(ids) THEN ids=array_replace(ids,sw.requester_id,sw.target_id);END IF;END LOOP; RETURN ids; END $$;
REVOKE ALL ON FUNCTION public.standby_track_ids(uuid,date,text) FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.is_on_standby(_user uuid,_date date) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE c uuid; BEGIN SELECT company_id INTO c FROM public.users WHERE id=_user; IF c IS NULL OR c IS DISTINCT FROM public.current_company_id() OR NOT public.member_is_active(auth.uid()) OR NOT public.company_module_access(c,'standby') THEN RETURN false;END IF;RETURN _user=ANY(public.standby_track_ids(c,_date,'technician')) OR _user=ANY(public.standby_track_ids(c,_date,'supervisor'));END $$;
CREATE OR REPLACE FUNCTION public.save_standby_track(_track text,_start date,_rotation_days int,_per_shift int,_order uuid[]) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE c uuid=public.current_company_id(); BEGIN
IF c IS NULL OR NOT public.member_is_active(auth.uid()) OR NOT public.is_company_manager() OR NOT public.company_module_access(c,'standby') THEN RAISE EXCEPTION 'On-call manager access required' USING ERRCODE='42501';END IF;
IF _track NOT IN ('technician','supervisor') OR _start IS NULL OR _rotation_days NOT IN(1,2,3,7,14) OR _order IS NULL OR _per_shift<1 OR (_per_shift>cardinality(_order) AND cardinality(_order)>0) OR (cardinality(_order)=0 AND _per_shift<>1) OR cardinality(_order)<>(SELECT count(DISTINCT x) FROM unnest(_order) x) THEN RAISE EXCEPTION 'Invalid roster settings';END IF;
IF EXISTS(SELECT 1 FROM unnest(_order) x WHERE NOT EXISTS(SELECT 1 FROM public.user_roles r WHERE r.user_id=x AND r.company_id=c AND r.role::text=_track AND public.member_is_active(x))) THEN RAISE EXCEPTION 'Choose active members of the same rota role';END IF;
PERFORM pg_advisory_xact_lock(hashtextextended(c::text||':standby',0));
IF _track='technician' THEN UPDATE public.company_settings SET standby_start=_start,standby_rotation_days=_rotation_days,standby_per_shift=_per_shift,standby_order=_order WHERE company_id=c;IF NOT FOUND THEN RAISE EXCEPTION 'Company settings must be initialized by an office admin';END IF;
ELSE INSERT INTO public.supervisor_rosters(company_id,start_date,rotation_days,per_shift,member_order,updated_by) VALUES(c,_start,_rotation_days,_per_shift,_order,auth.uid()) ON CONFLICT(company_id) DO UPDATE SET start_date=excluded.start_date,rotation_days=excluded.rotation_days,per_shift=excluded.per_shift,member_order=excluded.member_order,updated_by=auth.uid(),updated_at=now();END IF;
INSERT INTO public.standby_roster_audit(company_id,track,config,changed_by) VALUES(c,_track,jsonb_build_object('start',_start,'rotationDays',_rotation_days,'perShift',_per_shift,'order',_order),auth.uid()); END $$;
REVOKE ALL ON FUNCTION public.save_standby_track(text,date,int,int,uuid[]) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.save_standby_track(text,date,int,int,uuid[]) TO authenticated;
CREATE OR REPLACE FUNCTION public.save_standby_roster(_start date,_rotation_days int,_per_shift int,_order uuid[]) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM public.save_standby_track('technician',_start,_rotation_days,_per_shift,_order);END $$;
CREATE OR REPLACE FUNCTION public.guard_standby_swap() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE d date; BEGIN
IF NEW.company_id IS DISTINCT FROM public.current_company_id() OR NOT public.member_is_active(auth.uid()) OR NOT public.company_module_access(NEW.company_id,'standby') THEN RAISE EXCEPTION 'On-call module unavailable';END IF;
PERFORM pg_advisory_xact_lock(hashtextextended(NEW.company_id::text||':standby',0));
IF NEW.status NOT IN('pending','accepted','declined','cancelled') THEN RAISE EXCEPTION 'Invalid swap status';END IF;
IF TG_OP='INSERT' THEN
NEW.end_date=coalesce(NEW.end_date,NEW.swap_date);IF NEW.requester_id IS DISTINCT FROM auth.uid() OR NEW.status<>'pending' OR NEW.end_date<NEW.swap_date OR NEW.end_date-NEW.swap_date>30 OR NEW.swap_date<current_date THEN RAISE EXCEPTION 'Choose your upcoming range of up to 31 days';END IF;
IF NEW.manager_approved OR NEW.approved_by IS NOT NULL OR NEW.approved_at IS NOT NULL THEN RAISE EXCEPTION 'Approval cannot be set on creation';END IF;
IF NOT EXISTS(SELECT 1 FROM public.user_roles WHERE company_id=NEW.company_id AND user_id=NEW.requester_id AND role::text=NEW.track AND public.member_is_active(user_id)) OR NOT EXISTS(SELECT 1 FROM public.user_roles WHERE company_id=NEW.company_id AND user_id=NEW.target_id AND role::text=NEW.track AND public.member_is_active(user_id)) THEN RAISE EXCEPTION 'Choose an active colleague from the same rota role';END IF;
FOR d IN SELECT generate_series(NEW.swap_date,NEW.end_date,interval '1 day')::date LOOP IF NOT NEW.requester_id=ANY(public.standby_track_ids(NEW.company_id,d,NEW.track)) OR NEW.target_id=ANY(public.standby_track_ids(NEW.company_id,d,NEW.track)) OR EXISTS(SELECT 1 FROM public.leave_requests WHERE company_id=NEW.company_id AND user_id=NEW.target_id AND status='approved' AND d BETWEEN start_date AND end_date) THEN RAISE EXCEPTION 'Select your on-call days; colleague must be free throughout';END IF;END LOOP;
IF EXISTS(SELECT 1 FROM public.standby_swaps WHERE company_id=NEW.company_id AND track=NEW.track AND status IN('pending','accepted') AND (requester_id IN(NEW.requester_id,NEW.target_id) OR target_id IN(NEW.requester_id,NEW.target_id)) AND swap_date<=NEW.end_date AND coalesce(end_date,swap_date)>=NEW.swap_date) THEN RAISE EXCEPTION 'A swap already covers these dates';END IF;
ELSE
IF NEW.track<>OLD.track OR NEW.swap_date<>OLD.swap_date OR NEW.end_date IS DISTINCT FROM OLD.end_date OR NEW.company_id<>OLD.company_id OR NEW.requester_id<>OLD.requester_id OR NEW.target_id<>OLD.target_id OR NEW.note IS DISTINCT FROM OLD.note THEN RAISE EXCEPTION 'Swap details cannot change';END IF;
IF NEW.status<>OLD.status THEN IF OLD.manager_approved THEN RAISE EXCEPTION 'Approved swap cannot be changed';END IF;IF NEW.status IN('accepted','declined') AND (OLD.status<>'pending' OR auth.uid()<>OLD.target_id) THEN RAISE EXCEPTION 'Only the colleague asked can answer a pending request';END IF;IF NEW.status='cancelled' AND NOT(auth.uid()=OLD.requester_id OR public.is_company_manager()) THEN RAISE EXCEPTION 'Only requester or manager can cancel';END IF;NEW.responded_at=now();END IF;
IF NEW.manager_approved IS DISTINCT FROM OLD.manager_approved THEN
IF NOT public.is_company_manager() OR OLD.status<>'accepted' OR NEW.status<>'accepted' OR NOT NEW.manager_approved OR auth.uid() IN(OLD.requester_id,OLD.target_id) THEN RAISE EXCEPTION 'An independent manager must approve an accepted swap';END IF;
IF NOT EXISTS(SELECT 1 FROM public.user_roles WHERE company_id=NEW.company_id AND user_id=NEW.target_id AND role::text=NEW.track AND public.member_is_active(user_id)) THEN RAISE EXCEPTION 'Colleague is no longer eligible';END IF;
FOR d IN SELECT generate_series(NEW.swap_date,NEW.end_date,interval '1 day')::date LOOP IF NOT NEW.requester_id=ANY(public.standby_track_ids(NEW.company_id,d,NEW.track)) OR NEW.target_id=ANY(public.standby_track_ids(NEW.company_id,d,NEW.track)) OR EXISTS(SELECT 1 FROM public.leave_requests WHERE company_id=NEW.company_id AND user_id=NEW.target_id AND status='approved' AND d BETWEEN start_date AND end_date) THEN RAISE EXCEPTION 'Roster or availability changed; cancel and request again';END IF;END LOOP;
NEW.approved_by=auth.uid();NEW.approved_at=now();ELSIF NEW.approved_by IS DISTINCT FROM OLD.approved_by OR NEW.approved_at IS DISTINCT FROM OLD.approved_at THEN RAISE EXCEPTION 'Approval audit cannot change';END IF;END IF;RETURN NEW;END $$;
CREATE POLICY skills_enabled_read ON public.company_skills AS RESTRICTIVE FOR SELECT TO authenticated USING(public.member_is_active(auth.uid()) AND public.company_module_access(company_id,'skills_dispatch'));
CREATE POLICY member_skills_enabled ON public.member_skills AS RESTRICTIVE FOR ALL TO authenticated USING(public.member_is_active(auth.uid()) AND public.company_module_access(company_id,'skills_dispatch')) WITH CHECK(public.member_is_active(auth.uid()) AND public.company_module_access(company_id,'skills_dispatch'));
CREATE OR REPLACE FUNCTION public.guard_member_skill_assignment() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.user_roles r WHERE r.user_id=NEW.user_id AND r.company_id=NEW.company_id AND r.role IN('technician','supervisor') AND public.member_is_active(r.user_id)) OR NOT EXISTS(SELECT 1 FROM public.company_skills s WHERE s.id=NEW.skill_id AND s.company_id=NEW.company_id AND NOT s.archived) THEN RAISE EXCEPTION 'Skills can only be assigned to active technicians and supervisors in this company';END IF;NEW.assigned_by=auth.uid();RETURN NEW;END $$;
CREATE TRIGGER member_skill_role_guard BEFORE INSERT ON public.member_skills FOR EACH ROW EXECUTE FUNCTION public.guard_member_skill_assignment();